  insert into public.products (id, slug, name, category_id, status, price, summary, description, details, composition, care, fit, fabric, sizes) values
    ('heavyweight-tee', 'heavyweight-tee', 'Heavyweight Tee', 'tops', 'active', 8500, 'Dense 240 gsm jersey with a close, ribbed neck.', 'Our foundation piece. A dense, slightly dry jersey that holds its shape through years of washing, cut straight through the body with a sleeve that ends just above the elbow.', array['240 gsm jersey', 'Ribbed crew neck', 'Straight body']::text[], '100% organic cotton', array['Wash cold, inside out', 'Dry flat in shade', 'Warm iron on reverse']::text[], 'True to size. Take your usual size for a clean fit, one up for a relaxed drape.', 'A compact, long-staple organic cotton knitted tight enough to feel almost dry in the hand. It is garment-dyed and washed before it reaches you, so it keeps its size and its line.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('mariner-long-sleeve', 'mariner-long-sleeve', 'Mariner Long Sleeve', 'tops', 'active', 14000, 'Yarn-dyed ink and bone stripe, cut with a wide boat neck.', 'The stripe is knitted in rather than printed, so it stays sharp. A wide boat neck and a long, narrow sleeve give it the proportions of the original naval shirt.', array['Yarn-dyed stripe', 'Boat neck', 'Long sleeve']::text[], '100% cotton, 220 gsm interlock', array['Wash cold', 'Do not tumble dry', 'Reshape while damp']::text[], 'Slim through the body. Size up if you plan to layer underneath.', 'An interlock cotton with the stripe knitted in from dyed yarn, so the edges stay crisp and never crack or fade the way a print does. Smooth on both faces.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('oxford-shirt', 'oxford-shirt', 'Oxford Shirt', 'shirts', 'active', 18000, 'Washed pale-blue oxford with a soft, unlined button-down collar.', 'A heavy oxford cloth, garment washed so it arrives already broken in. The collar is unlined and rolls rather than lies flat; the single chest pocket is cut on the grain.', array['Button-down collar', 'Single chest pocket', 'Curved hem']::text[], '100% cotton oxford', array['Wash at 30°C', 'Hang to dry', 'Iron while damp']::text[], 'Relaxed. Sleeve length is generous; consider sizing down if between sizes.', 'A heavy oxford woven with a white weft through a pale blue warp, which gives the cloth its soft, broken colour. Washed after sewing for a lived-in hand from the first wear.', array['S', 'M', 'L', 'XL']::text[]),
    ('lambswool-cardigan', 'lambswool-cardigan', 'Lambswool Cardigan', 'knitwear', 'active', 36000, 'Chunky moss lambswool with corozo buttons and deep ribbed trims.', 'Knitted on a coarse gauge for a substantial, lofty hand. The V-neck sits low enough to wear over a shirt; the ribbed cuffs and hem are knitted twice as deep as usual so they keep their grip.', array['5-gauge knit', 'Corozo buttons', 'Deep ribbed trims']::text[], '100% lambswool', array['Hand wash cold', 'Dry flat', 'Fold, never hang, for storage']::text[], 'Relaxed with a dropped shoulder. Take your usual size.', 'Lambswool from the first shearing, spun loosely and knitted on a coarse five-gauge machine. The result is light for its bulk, warm, and slowly softens with each wear.', array['S', 'M', 'L', 'XL']::text[]),
    ('henley', 'henley', 'Long-Sleeve Henley', 'tops', 'active', 12000, 'Slub jersey in rust, with a three-button placket.', 'An irregular slub yarn gives the jersey a faint, uneven texture that softens with wear. Three horn buttons on a short placket; long sleeves finished with a narrow rib.', array['Slub jersey', 'Three-button placket', 'Ribbed cuffs']::text[], '100% cotton', array['Wash cold', 'Dry flat', 'Cool iron']::text[], 'Regular fit, close at the cuff.', 'Slub yarn is spun deliberately uneven, so the jersey carries a faint irregular texture. Garment-dyed in rust, it fades gently and evenly over time.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('fleece-hoodie', 'fleece-hoodie', 'Fleece Hoodie', 'sweats', 'active', 21000, 'Brushed-back 400 gsm fleece in grey marl. No prints, no branding.', 'A heavy loopback fleece, brushed on the inside. The hood is double layered so it holds its shape, with flat cotton drawcords and a single kangaroo pocket.', array['400 gsm fleece', 'Double-layer hood', 'Kangaroo pocket']::text[], '80% cotton, 20% recycled polyester', array['Wash cold, inside out', 'Do not tumble dry']::text[], 'Relaxed through the body, ribbed at the cuff and hem.', 'A 400 gsm loopback fleece, brushed on the reverse for warmth and left smooth outside. The grey marl comes from blending undyed and black fibres before spinning.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('fleece-crew', 'fleece-crew', 'Fleece Crew', 'sweats', 'active', 18500, 'The same heavy fleece as the hoodie, as a clean crewneck in oat.', 'Cut from the hoodie''s 400 gsm loopback fleece with a set-in sleeve and a deep ribbed neck that stays flat. A quieter alternative to knitwear in the colder months.', array['400 gsm fleece', 'Set-in sleeve', 'Ribbed trims']::text[], '80% cotton, 20% recycled polyester', array['Wash cold, inside out', 'Do not tumble dry']::text[], 'Relaxed. Take your usual size.', 'The hoodie''s 400 gsm loopback fleece, dyed a warm undyed-looking oat. Brushed inside, smooth outside, with ribs knitted from the same yarn.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('pique-polo', 'pique-polo', 'Piqué Polo', 'tops', 'active', 13500, 'Bottle-green cotton piqué with a two-button placket.', 'A fine double piqué that is crisp to the touch and breathes in warm weather. The collar is knitted rather than cut, so it keeps its roll.', array['Double piqué', 'Knitted collar', 'Two-button placket']::text[], '100% cotton', array['Wash at 30°C', 'Dry flat']::text[], 'Regular fit, slightly shorter in the body.', 'A double piqué knitted from fine combed cotton: crisp, breathable, with a small honeycomb texture that holds a dyed colour deeply.', array['XS', 'S', 'M', 'L', 'XL']::text[])
