-- STILLFORM · starter data
--
-- Generated by scripts/build-seed.mjs from src/catalog/local. Do not edit by hand.
-- Loads the demo collection into an empty store. If the store already has
-- products or media, nothing is changed, so running it again is always safe.

do $seed$
begin
  if exists (select 1 from public.products) or exists (select 1 from public.media) then
    raise notice 'STILLFORM seed skipped: the store already has content.';
    return;
  end if;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  on conflict do nothing;

  update public.store_settings set
    name = 'STILLFORM',
    description = 'A small collection of heavyweight garments, cut once and cut well.',
    currency = 'USD',
    locale = 'en-US',
    low_stock_threshold = 3,
    order_prefix = 'SF',
    contact = '{"email":"studio@stillform.example","phone":"","address":""}'::jsonb,
    rail = '{"eyebrow":"Collection 01 · Autumn–Winter 2026","heading":"Clothes that keep their form.","caption":"Run a hand along the rail. Click a piece to take it down.","touchCaption":"Swipe along the rail, then tap a piece to bring it forward.","autoplay":false}'::jsonb,
    home = '{"statement":{"label":"The house","body":"We make a small number of garments in heavy, honest cloth, and we keep making them.","aside":"No prints on the outside, no seasonal markdowns. Each piece is cut to be worn for years, and to hang well on the days it isn''t.","mediaId":"editorial/detail-lambswool"},"featuredCollectionId":"collection-01","lookbookId":"lookbook-01"}'::jsonb,
    footer = '{"note":"A preview of the STILLFORM storefront. Orders and payments are not yet enabled.","links":[{"label":"Shop all","href":"/shop"},{"label":"Collection 01","href":"/#collection"},{"label":"Lookbook","href":"/#lookbook"},{"label":"Shipping and returns","href":"/info"}]}'::jsonb,
    checkout = '{"enabled":false,"methods":[{"id":"cod","label":"Cash on delivery","instructions":"Pay the courier in cash or by card when your order arrives.","enabled":true},{"id":"bank-transfer","label":"Bank transfer","instructions":"We will email our bank details with your order reference. Your order ships once payment arrives.","enabled":false},{"id":"pickup","label":"Pay at studio pickup","instructions":"Collect and pay at the studio. We will email you when your order is ready.","enabled":false}]}'::jsonb,
    shipping = '{"flatRate":0,"freeOver":null,"note":"Shipping is included in the price. Prices include applicable taxes."}'::jsonb,
    policies = '{"shipping":"Orders are packed by hand and dispatched within three working days. You will receive your tracking details by email.","returns":"Unworn pieces can be returned within 30 days of delivery for a full refund. Contact the studio with your order reference to arrange a return."}'::jsonb
  where id;

  raise notice 'STILLFORM seed loaded: % products.', (select count(*) from public.products);
end;
$seed$;
